                id="fullName"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-required="true"
                aria-describedby="fullName-error"
                placeholder="Jane Doe"
              />
              <p id="fullName-error" class="field-error" aria-live="polite"></p>
