            <input
              class="field-input"
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
              placeholder="+1 555 123 4567"
            />
            <p id="phone-help" class="field-help">Optional. Use a number like +1 555 123 4567 or 555-123-4567.</p>
            <p id="phone-error" class="field-error" aria-live="polite"></p>
          </div>

          <div class="actions">
            <button class="submit-button" type="submit">Send message</button>
          </div>
        </form>
      </section>
    </main>

    <footer>
      <p class="support-note">We’ll only use your contact details to respond to this support request.</p>
    </footer>
  </div>

  <script>
    (() => {
      const form = document.getElementById("support-form");
      const fields = ["fullName", "email", "phone"];
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        touched: {
          fullName: false,
          email: false,
          phone: false
        },
        submitted: false
      };

      function getInput(name) {
        return document.getElementById(name);
      }

      function getErrorEl(name) {
        return document.getElementById(`${name}-error`);
      }

      function validateField(name, value) {
        const trimmed = value.trim();

        if (name === "fullName") {
          if (!trimmed) {
            return "Please enter your full name.";
          }
          return "";
        }

        if (name === "email") {
          if (!trimmed) {
            return "Please enter your email address.";
          }
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
            return "Enter a valid email address, such as name@example.com.";
          }
          return "";
        }

        if (!trimmed) {
          return "";
        }

        const digitsOnly = trimmed.replace(/\D/g, "");
        const validCharacters = /^[0-9()+.\-\s]+$/.test(trimmed);

        if (!validCharacters || digitsOnly.length < 7 || digitsOnly.length > 15) {
          return "Enter a valid phone number, such as +1 555 123 4567.";
        }

        return "";
      }

      function shouldShowError(name) {
        return state.touched[name] || state.submitted;
      }

      function syncField(name) {
        const input = getInput(name);
        const errorEl = getErrorEl(name);
        const error = shouldShowError(name) ? validateField(name, state.values[name]) : "";

        input.setAttribute("aria-invalid", error ? "true" : "false");
        errorEl.textContent = error;
        errorEl.classList.toggle("is-visible", Boolean(error));
      }

      function syncAll() {
        fields.forEach(syncField);
      }

      function focusFirstInvalid() {
        const firstInvalid = form.querySelector('[aria-invalid="true"]');
        if (firstInvalid) {
          firstInvalid.focus();
        }
      }

      fields.forEach((name) => {
        const input = getInput(name);

        input.addEventListener("blur", () => {
          state.touched[name] = true;
          state.values[name] = input.value;
          syncField(name);
        });

        input.addEventListener("input", () => {
          state.values[name] = input.value;
          if (state.touched[name] || state.submitted) {
            syncField(name);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;

        fields.forEach((name) => {
          state.values[name] = getInput(name).value;
        });

        syncAll();

        const hasError = fields.some((name) => validateField(name, state.values[name]));
        if (hasError) {
          window.requestAnimationFrame(focusFirstInvalid);
        }
      });
    })();
  </script>
